import{_ as d,a0 as l,w as a,s as r,ao as p,I as n,x as t,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"介绍 Linux 中的管道和命名管道 | LCTT x X-CMD","titleTemplate":false,"description":"介绍 Linux 中的管道和命名管道 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"介绍 Linux 中的管道和命名管道 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"介绍 Linux 中的管道和命名管道 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180823 An introduction to pipes and named pipes in Linux","title":"介绍 Linux 中的管道和命名管道","tag":"201809","desc":""},"relativePath":"201809/20180823 An introduction to pipes and named pipes in Linux.md","filePath":"[post].md"}'),u={name:"201809/20180823 An introduction to pipes and named pipes in Linux.md"};function c(m,e,g,f,k,x){const i=l("Link");return a(),r("div",null,[e[18]||(e[18]=p('<h1 id="介绍-linux-中的管道和命名管道" tabindex="-1">介绍 Linux 中的管道和命名管道 <a class="header-anchor" href="#介绍-linux-中的管道和命名管道" aria-label="Permalink to “介绍 Linux 中的管道和命名管道”">​</a></h1><blockquote><p>要在命令间移动数据？使用管道可使此过程便捷。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/LAW-Internet_construction_9401467_520x292_0512_dc.png?itok=RPkPPtDe" alt=""></p><p>在 Linux 中，<code>pipe</code> 能让你将一个命令的输出发送给另一个命令。管道，如它的名称那样，能重定向一个进程的标准输出、输入和错误到另一个进程，以便于进一步处理。</p><p>“管道”（或称“未命名管道”）命令的语法是在两个命令之间加上 <code>|</code> 字符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Command-1 | Command-2 | ...| Command-N</span></span></code></pre></div><p>这里，该管道不能通过另一个会话访问；它被临时创建用于接收 <code>Command-1</code> 的执行并重定向标准输出。它在成功执行之后删除。</p><p><img src="https://opensource.com/sites/default/files/uploads/pipe.png" alt=""></p><p>在上面的示例中，<code>contents.txt</code> 包含特定目录中所有文件的列表 —— 具体来说，就是 <code>ls -al</code> 命令的输出。我们首先通过管道（如图所示）使用 “file” 关键字从 <code>contents.txt</code> 中 <code>grep</code> 文件名，因此 <code>cat</code> 命令的输出作为 <code>grep</code> 命令的输入提供。接下来，我们添加管道来执行 <code>awk</code> 命令，该命令显示 <code>grep</code> 命令的过滤输出中的第 9 列。我们还可以使用 <code>wc -l</code> 命令计算 <code>contents.txt</code> 中的行数。</p>',9)),n("p",null,[e[1]||(e[1]=t("只要系统启动并运行或直到它被删除，命名管道就可以持续使用。它是一个遵循 ",-1)),s(i,{href:"https://en.wikipedia.org/wiki/FIFO_(computing_and_electronics)"},{default:o(()=>[...e[0]||(e[0]=[t("FIFO",-1)])]),_:1}),e[2]||(e[2]=t("（先进先出）机制的特殊文件。它可以像普通文件一样使用。也就是，你可以写入，从中读取，然后打开或关闭它。要创建命名管道，命令为：",-1))]),e[19]||(e[19]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkfifo &lt;pipe-name&gt;</span></span></code></pre></div><p>这将创建一个命名管道文件，它甚至可以在多个 shell 会话中使用。</p><p>创建 FIFO 命名管道的另一种方法是使用此命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mknod p &lt;pipe-name&gt;</span></span></code></pre></div><p>要重定向任何命令的标准输出到其它命令，请使用 <code>&gt;</code> 符号。要重定向任何命令的标准输入，请使用 <code>&lt;</code> 符号。</p><p><img src="https://opensource.com/sites/default/files/uploads/redirection.png" alt=""></p><p>如上所示，<code>ls -al</code> 命令的输出被重定向到 <code>contents.txt</code> 并插入到文件中。类似地，<code>tail</code> 命令的输入通过 <code>&lt;</code> 符号从 <code>contents.txt</code> 读取。</p><p><img src="https://opensource.com/sites/default/files/uploads/create-named-pipe.png" alt=""></p><p><img src="https://opensource.com/sites/default/files/uploads/verify-output.png" alt=""></p><p>这里，我们创建了一个命名管道 <code>my-named-pipe</code>，并将 <code>ls -al</code> 命令的输出重定向到命名管道。我们可以打开一个新的 shell 会话并 <code>cat</code> 命名管道的内容，如前所述，它显示了 <code>ls -al</code> 命令的输出。请注意，命名管道的大小为零，并有一个标志 “p”。</p><p>因此，下次你在 Linux 终端上使用命令并在命令之间移动数据时，希望管道使这个过程快速简便。</p><hr>',12)),n("p",null,[e[4]||(e[4]=t("via: ",-1)),s(i,{href:"https://opensource.com/article/18/8/introduction-pipes-linux"},{default:o(()=>[...e[3]||(e[3]=[t("https://opensource.com/article/18/8/introduction-pipes-linux",-1)])]),_:1})]),n("p",null,[e[9]||(e[9]=t("作者：",-1)),s(i,{href:"https://opensource.com/users/architmodi"},{default:o(()=>[...e[5]||(e[5]=[t("Archit Modi",-1)])]),_:1}),e[10]||(e[10]=t(" 选题：",-1)),s(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[6]||(e[6]=[t("lujun9972",-1)])]),_:1}),e[11]||(e[11]=t(" 译者：",-1)),s(i,{href:"https://github.com/geekpi"},{default:o(()=>[...e[7]||(e[7]=[t("geekpi",-1)])]),_:1}),e[12]||(e[12]=t(" 校对：",-1)),s(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原创编译，",-1)),s(i,{href:"https://linux.cn/"},{default:o(()=>[...e[14]||(e[14]=[t("Linux中国",-1)])]),_:1}),e[17]||(e[17]=t(" 荣誉推出",-1))])])}const C=d(u,[["render",c]]);export{T as __pageData,C as default};
